import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0088: Bootstrap Typechecker (plugin-engine-typecheck)","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0088-bootstrap-typechecker.md","filePath":"vendored/handl/project/adrs/0088-bootstrap-typechecker.md"}`),a={name:`handl/project/adrs/0088-bootstrap-typechecker.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0088-bootstrap-typechecker-plugin-engine-typecheck" tabindex="-1">ADR-0088: Bootstrap Typechecker (<code>plugin-engine-typecheck</code>) <a class="header-anchor" href="#adr-0088-bootstrap-typechecker-plugin-engine-typecheck" aria-label="Permalink to “ADR-0088: Bootstrap Typechecker (plugin-engine-typecheck)”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Implemented (merged to main). Part of the bootstrap tooling strategy (<a href="./0085-bootstrap-tooling-strategy.html">ADR-0085</a>). Builds on <a href="./0054-generic-typecheck-engine.html">ADR-0054 — Generic Typecheck Engine</a>, <a href="./0052-arrow-calculus-kernel.html">ADR-0052</a>, and <a href="./0074-arrow-syntax-v0_1-surface-redesign.html">ADR-0074</a>. Temporary: will be replaced by the self-hosted typechecker described in <a href="./../rfcs/0004-typechecker-in-handl.html">RFC-0004</a>.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Arrow kind checking and the structural type inference sketched in ADR-0074 (ID.7, row variables, <code>rec</code> region typing per <code>research/arrow-calculus-kernel-poc/ARROW_REC_TYPING_V0_1.md</code>) do not exist as a usable, per-file checking pass. The stdlib cannot be written with any confidence about types until something checks it. The existing <code>plugin-engine-typecheck*</code> crates target the eval-engine value model, not the v0.1 surface AST.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>The surface-level checking work lands in the existing typecheck crates — <code>plugin-engine-typecheck</code> (with <code>plugin-typecheck-core</code> / <code>plugin-typecheck-nbe</code> where the machinery fits) — extended with a <strong>bootstrap check pass over the v0.1 surface AST</strong>. It is a bootstrap checker, not the final inference engine: it implements the decidable core of ADR-0074&#39;s typing rules and returns actionable diagnostics (shared types from <code>plugin-ext-diag</code>, ADR-0091); row-variable inference and full <code>rec</code> fixpoint typing stay behind explicit <code>todo!</code> boundaries with diagnostics that say &quot;not yet checked&quot; rather than silently passing.</p><ul><li><p><strong>Scope (v0.1):</strong></p><ol><li>Arrow kind checking of composed graphs (<code>arr</code>/<code>&gt;&gt;&gt;</code>/<code>first</code>/<code>choice</code> /<code>loop</code>/<code>app</code> arities and wire types per ADR-0052).</li><li>Structural type inference for literals, records, positional structures, and projections (per ADR-0074 §types).</li><li><code>rec</code> region well-formedness: feedback wires are consumed exactly where produced, no phantom feedback (per the rec-typing reference).</li><li>Module-level checks: every import projection used, every exported name bound, no duplicate bindings.</li></ol></li><li><p><strong>Not in scope (deferred to RFC-0004):</strong> trait/impl checking (ADR-0075), refinement inference (ADR-0070), state-machine invariants (ADR-0073), polymorphic instantiation over row variables.</p></li><li><p><strong>API surface:</strong></p><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">pub</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> check_module</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">src</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;">str</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Result</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&lt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">TypecheckReport</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> ParseError</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&gt;;</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">pub</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> struct</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> TypecheckReport</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> {</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> pub</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> diagnostics</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Vec</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&lt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">Diagnostic</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&gt;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> }</span></span></code></pre></div><p><code>Diagnostic</code> comes from <code>plugin-ext-diag</code> (ADR-0091) — no local variant types in the typecheck crates.</p></li><li><p><strong>Architecture:</strong> single pass composition — collect bindings → infer expression types bottom-up by AST child roles (ADR-0081) → unify structurally with spans retained → report. Error recovery: report all diagnostics per module, not first failure.</p></li><li><p><strong>Testing:</strong> 100% coverage. Table-driven <code>tests/</code> per typing rule from ADR-0074 and the grammar spec; golden typecheck reports; CI runs it over all <code>handl-packages/</code> and <code>examples/</code> <code>.handl</code> files (must be clean).</p></li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The stdlib gets real feedback while it is being written in handl.</li><li>Deliberately incomplete inference means some valid v0.1 programs are rejected with &quot;not yet checked&quot; — acceptable and documented; the RFC-0004 engine replaces these boundaries.</li><li>The checker lives inside the generic <code>plugin-engine-typecheck</code> machinery (parsing/unification infrastructure) rather than forking it; what is new here is the surface-AST-level pass and its diagnostics. Keeping the engine generic preserves replaceability per ADR-0085.</li></ul><h2 id="status-1" tabindex="-1">Status <a class="header-anchor" href="#status-1" aria-label="Permalink to “Status”">​</a></h2><p>Implemented (merged to main).</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};